import fs from 'fs'
import crypto from 'crypto'

let CurrentLsnPicking   = lsnToNumber("0000122A:000281B8:0002")
let CurrentLsnShopOrder = lsnToNumber("0000122A:00027D50:0004")

function getNextShopOrderLsn() {
    CurrentLsnShopOrder = CurrentLsnShopOrder + BigInt(getRandomInt(1, 10));

    return numberToLsn(CurrentLsnShopOrder);
}

function getNextPickingLsn() {
    CurrentLsnPicking = CurrentLsnPicking + BigInt(getRandomInt(1, 10));
    return numberToLsn(CurrentLsnPicking);
}

function lsnToNumber(hex) {
    const cleanedHex = hex.replaceAll(/[^\da-f]/gi, '').toLowerCase();
    const hexString = cleanedHex.toString('hex');
    const bigIntValue = BigInt(`0x${hexString}`);
    return bigIntValue;
}

function numberToLsn(lsn) {
    lsn = lsn.toString(16)
        .padStart(20, '0');
    const part1 = lsn.slice(0, 8);
    const part2 = lsn.slice(8, 16);
    const part3 = lsn.slice(16, 20);

    return `${part1}:${part2}:${part3}`;
}

function getRandomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

async function createShopOrder(client) {
    const shopOrderMessage = JSON.parse(fs.readFileSync('shoporder_create/shopOrders.json'));
    const pickingOrderMessage = JSON.parse(fs.readFileSync('shoporder_create/pickingOrders.json'));
    const uniqueId = `${crypto.randomUUID().split('-')[0]}_${crypto.randomUUID().split('-')[1]}_${crypto.randomUUID().split('-')[2]}`;

    shopOrderMessage.payload.HANDLE = shopOrderMessage.payload.HANDLE.replace('12345678620240731_2', `_${uniqueId}`);
    shopOrderMessage.payload.SHOP_ORDER = shopOrderMessage.payload.SHOP_ORDER.replace('12345678620240731_2', `_${uniqueId}`);
    shopOrderMessage.payload.__source_ts_ms = Date.now();
    shopOrderMessage.payload.__source_change_lsn = getNextShopOrderLsn();

    pickingOrderMessage.payload.S_HANDLE = pickingOrderMessage.payload.S_HANDLE.replace('12345678620240731_2', `_${uniqueId}`);
    pickingOrderMessage.payload.S_SHOP_ORDER = pickingOrderMessage.payload.S_SHOP_ORDER.replace('12345678620240731_2', `_${uniqueId}`);
    await sleep(5);
    pickingOrderMessage.payload.__source_ts_ms = Date.now();
    pickingOrderMessage.payload.__source_change_lsn = getNextPickingLsn();


    await client.binding.send('shop-order', 'create', shopOrderMessage);
    console.log(`Sent Creation Shop Order: '${shopOrderMessage.payload.SHOP_ORDER}', with t=${shopOrderMessage.payload.__source_ts_ms}`)
    await client.binding.send('picking-order', 'create', pickingOrderMessage);
    console.log(`Sent Creation Picking Order: '${pickingOrderMessage.payload.S_SHOP_ORDER}'with t=${pickingOrderMessage.payload.__source_ts_ms}`)

    return {
        handle: shopOrderMessage.payload.HANDLE,
        shop_order: shopOrderMessage.payload.SHOP_ORDER
    };
}

async function updateShopOrder(client, { handle, shop_order }) {
    const shopOrderMessage = JSON.parse(fs.readFileSync('shoporder_create/shopOrders.json'));
    const pickingOrderMessage = JSON.parse(fs.readFileSync('shoporder_create/pickingOrders.json'));

    shopOrderMessage.payload.HANDLE     = handle;
    shopOrderMessage.payload.SHOP_ORDER = shop_order;
    shopOrderMessage.payload.__source_ts_ms = Date.now();
    shopOrderMessage.payload.QTY_TO_BUILD = pickingOrderMessage.payload.QTY_TO_BUILD + getRandomInt(1, 10);
    shopOrderMessage.payload.__source_change_lsn = getNextShopOrderLsn();
    shopOrderMessage.payload.__op = "u";

    pickingOrderMessage.payload.S_HANDLE     = handle;
    pickingOrderMessage.payload.S_SHOP_ORDER = shop_order;
    await sleep(5);
    pickingOrderMessage.payload.__source_ts_ms = Date.now();
    pickingOrderMessage.payload.D_SOURCE_LOC = "PR10";
    pickingOrderMessage.payload.D_DESTINATION_LOC = "PR11";
    pickingOrderMessage.payload.__source_change_lsn = getNextPickingLsn();
    pickingOrderMessage.payload.__op = "u";

    await client.binding.send('shop-order', 'create', shopOrderMessage);
    console.log(`Sent Update Shop Order: '${shopOrderMessage.payload.SHOP_ORDER}', with t=${shopOrderMessage.payload.__source_ts_ms}`)
    await client.binding.send('picking-order', 'create', pickingOrderMessage);
    console.log(`Sent Update Picking Order: '${pickingOrderMessage.payload.S_SHOP_ORDER}', with t=${pickingOrderMessage.payload.__source_ts_ms}`)
}

function sleep(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
}

export async function processWithDelay(delayInMilliseconds, count, client) {
    const orders = []
    for (let i = 0; i < count; i++) {
        const shopOrder = await createShopOrder(client);
        orders.push(shopOrder)
        await sleep(getRandomInt(1, delayInMilliseconds));
        await updateShopOrder(client, shopOrder);
        await sleep(getRandomInt(1, delayInMilliseconds));
    }

    return orders;
}
